# Tiling-consistency idea: for each candidate window, extend periodically (test periods 2..8) and count mismatched non-marker cells; the answer tile maximizes consistency.
def score(i, w, rr, cc, p, q):
    H,W=i.shape; m=(i==3)
    sub=i[rr:rr+4,cc:cc+4]
    cnt=0; tot=0
    for r in range(H):
        for c in range(W):
            if m[r,c]: continue
            R=r-p*(r//p); C=c-q*(c//q)
            if R<rr or C<cc or R>=rr+4 or C>=cc+4: continue
            tot+=1; cnt += int(sub[R-rr,C-cc]==i[r,c])
    return cnt/tot if tot else -1
